import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry, PointLight } = THREE;

  const root = new Group();
  root.name = config.id || 'journal-card-3';

  const content = new Group();
  content.name = 'journal-card-content';
  root.add(content);

  const timelines = [];
  const resources = [];
  let disposed = false;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: true
  });
  const backdropUv = uv();
  const backdropBlend = smoothstep(0.05, 0.95, backdropUv.y);
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(vec3(0.086, 0.086, 0.114), vec3(0.91, 0.925, 0.949), backdropBlend.mul(0.035)),
    backdropBlend.mul(0.48)
  );
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'journal-card-backdrop';
  backdrop.position.set(0, 0, -2.5);
  content.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new CircleGeometry(1.55, 48);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: 0x0b0b10,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const contactShadow = new Mesh(shadowGeometry, shadowMaterial);
  contactShadow.name = 'journal-card-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.scale.set(1.25, 0.52, 1);
  contactShadow.position.set(0, -0.95, -0.32);
  content.add(contactShadow);
  resources.push(shadowGeometry, shadowMaterial);

  const cardWidth = 2.35;
  const cardHeight = 1.47;
  const cardGeometry = new PlaneGeometry(cardWidth, cardHeight);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: 0xe8ecf2,
    transparent: false
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.name = 'journal-card-image';
  card.position.z = 0;
  content.add(card);
  resources.push(cardGeometry, cardMaterial);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  const frameMaterial = new MeshStandardNodeMaterial({
    color: 0x16161d,
    roughness: 0.58,
    metalness: 0.48
  });
  resources.push(frameMaterial);

  const edgeMaterial = new MeshStandardNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.05,
    roughness: 0.52,
    metalness: 0.28,
    transparent: true,
    opacity: 0.9
  });
  resources.push(edgeMaterial);

  const frameDepth = 0.08;
  const frameThickness = 0.07;
  const framePieces = [
    [cardWidth + frameThickness, frameThickness, frameDepth, 0, cardHeight / 2 + frameThickness / 2, 0.08],
    [cardWidth + frameThickness, frameThickness, frameDepth, 0, -cardHeight / 2 - frameThickness / 2, 0.08],
    [frameThickness, cardHeight, frameDepth, -cardWidth / 2 - frameThickness / 2, 0, 0.08],
    [frameThickness, cardHeight, frameDepth, cardWidth / 2 + frameThickness / 2, 0, 0.08]
  ];

  const frameGroup = new Group();
  frameGroup.name = 'machined-frame';
  content.add(frameGroup);

  for (const [w, h, d, x, y, z] of framePieces) {
    const geometry = new BoxGeometry(w, h, d);
    const mesh = new Mesh(geometry, frameMaterial);
    mesh.position.set(x, y, z);
    frameGroup.add(mesh);
    resources.push(geometry);
  }

  const accentGroup = new Group();
  accentGroup.name = 'accent-focus-edge';
  accentGroup.visible = false;
  content.add(accentGroup);

  const accentPieces = [
    [cardWidth + 0.12, 0.018, 0.018, 0, cardHeight / 2 + 0.045, 0.14],
    [0.018, cardHeight, 0.018, cardWidth / 2 + 0.045, 0, 0.14]
  ];

  for (const [w, h, d, x, y, z] of accentPieces) {
    const geometry = new BoxGeometry(w, h, d);
    const mesh = new Mesh(geometry, edgeMaterial);
    mesh.position.set(x, y, z);
    accentGroup.add(mesh);
    resources.push(geometry);
  }

  const rimLight = new PointLight(0xff2a38, 0.72, 4.5, 2);
  rimLight.name = 'signal-red-rim';
  rimLight.position.set(1.2, 1.2, 1.3);
  content.add(rimLight);

  const fillLight = new PointLight(0xe8ecf2, 0.45, 4, 2);
  fillLight.name = 'paper-fill';
  fillLight.position.set(-1.5, -0.7, 1.8);
  content.add(fillLight);

  const setAccent = (active) => {
    accentGroup.visible = active;
    if (active) {
      const timeline = gsap.timeline();
      timeline.fromTo(
        accentGroup.scale,
        { x: 0.96, y: 0.96, z: 0.96 },
        { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power2.out' }
      );
      timelines.push(timeline);
    }
  };

  const handlers = {
    hover: (active = true) => {
      const timeline = gsap.timeline();
      timeline.to(content.position, {
        y: active ? 0.15 : 0,
        duration: 0.32,
        ease: 'power3.out'
      });
      timelines.push(timeline);
    },
    click: () => {
      const timeline = gsap.timeline();
      timeline.to(content.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      }).to(content.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.3,
        ease: 'back.out(2)'
      });
      timelines.push(timeline);
      ctx.emit('hub-journal.select', {
        nodeId: config.id || 'journal-card-3'
      });
    },
    focus: () => setAccent(true),
    blur: () => setAccent(false)
  };

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }
    timelines.length = 0;

    for (const resource of resources) {
      if (resource?.dispose) resource.dispose();
    }
    resources.length = 0;

    root.userData.handlers = {};
  };

  return root;
}
